#include <bits/stdc++.h>
using namespace std;

const long long BASE = 256;         // treat characters as base-256 digits
const long long MOD  = 1000000007;  // large prime modulus

vector<int> rabinKarp(const string& text, const string& pattern) {
    int n = text.size();
    int m = pattern.size();
    vector<int> matches;
    if (m == 0 || m > n) return matches;

    long long patternHash = 0;
    long long windowHash  = 0;
    long long highOrder   = 1;   // BASE^(m-1) % MOD, used to drop the leading digit

    for (int i = 0; i < m - 1; i++) {
        highOrder = (highOrder * BASE) % MOD;
    }

    for (int i = 0; i < m; i++) {
        patternHash = (patternHash * BASE + pattern[i]) % MOD;
        windowHash  = (windowHash * BASE + text[i]) % MOD;
    }

    for (int i = 0; i + m <= n; i++) {
        if (patternHash == windowHash) {
            if (text.compare(i, m, pattern) == 0) {
                matches.push_back(i);
            }
        }

        if (i + m < n) {
            windowHash = (windowHash - (long long)text[i] * highOrder % MOD + MOD) % MOD;
            windowHash = (windowHash * BASE + text[i + m]) % MOD;
        }
    }

    return matches;
}

int main() {
    string text = "ababab";
    string pattern = "aba";

    vector<int> hits = rabinKarp(text, pattern);
    for (int idx : hits) {
        cout << "Match at index " << idx << "\n";
    }
    return 0;
}

vector<pair<int,int>> rabinKarpMulti(const string& text, const vector<string>& patterns) {
    int m = patterns[0].size();
    int n = text.size();
    unordered_map<long long, vector<int>> hashToPatterns;

    long long highOrder = 1;
    for (int i = 0; i < m - 1; i++) highOrder = (highOrder * BASE) % MOD;

    for (int p = 0; p < (int)patterns.size(); p++) {
        long long h = 0;
        for (char c : patterns[p]) h = (h * BASE + c) % MOD;
        hashToPatterns[h].push_back(p);
    }

    vector<pair<int,int>> matches;  // (text index, pattern index)
    long long windowHash = 0;
    for (int i = 0; i < m; i++) windowHash = (windowHash * BASE + text[i]) % MOD;

    for (int i = 0; i + m <= n; i++) {
        auto it = hashToPatterns.find(windowHash);
        if (it != hashToPatterns.end()) {
            for (int p : it->second) {
                if (text.compare(i, m, patterns[p]) == 0) {
                    matches.push_back({i, p});
                }
            }
        }
        if (i + m < n) {
            windowHash = (windowHash - (long long)text[i] * highOrder % MOD + MOD) % MOD;
            windowHash = (windowHash * BASE + text[i + m]) % MOD;
        }
    }
    return matches;
}
